Rules: 02

```ts
import { type Result, ok, err } from '@tenets/result';

type CreateInvoiceInput = { customerId: string; amountCents: number };
type CreateInvoiceError = { type: 'unknown_customer'; customerId: string };
type Invoice = { customerId: string; amountCents: number };

function createInvoice(
	input: CreateInvoiceInput,
	knownCustomerIds: ReadonlySet<string>,
): Result<Invoice, CreateInvoiceError> {
	if (!knownCustomerIds.has(input.customerId)) {
		return err({ type: 'unknown_customer', customerId: input.customerId });
	}
	return ok({ customerId: input.customerId, amountCents: input.amountCents });
}
```

Unknown customer = recoverable, caller branch on it → `Result`, not invariant. `knownCustomerIds` param stand for real lookup (DB/repo) — swap when store exist.

